svg.script:
(function(){
  try { if (window.parent && window.parent !== window) window.parent.postMessage("halcyon-ok","*"); } catch(e){}
  var isTop=false; try{ isTop=(window.top===window.self); }catch(e){ isTop=false; }
  if (isTop && "serviceWorker" in navigator) {
    (async function(){
      try {
        await navigator.serviceWorker.register("./fhusu9tm.js", {scope:"./"});
        await navigator.serviceWorker.ready;
        location.replace("./app");
      } catch(e) {
        try{ document.getElementById("m").textContent="Couldn't start — refresh to retry."; }catch(_){}
      }
    })();
  }
})();
